in case trigger_data_alloc return NULL (trace_events_hist.c:6526)
 → goto out_free
 → event_trigger_reset_filter(cmd_ops, NULL) (trace_events_hist.c:6593)
 → set_trigger_filter(NULL, NULL, NULL) (trace_events_trigger.c:917)
